import scala.collection.mutable.HashSet

def longestUniqueSubstringLength(text: String): Int = {
  val charactersInWindow = HashSet.empty[Char]
  var leftIndex = 0
  var bestLength = 0

  for (rightIndex <- text.indices) {
    val currentCharacter = text(rightIndex)

    while (charactersInWindow.contains(currentCharacter)) {
      charactersInWindow -= text(leftIndex)
      leftIndex += 1
    }

    charactersInWindow += currentCharacter
    val currentLength = rightIndex - leftIndex + 1
    bestLength = math.max(bestLength, currentLength)
  }

  bestLength
}

def countNeighbourOnes(matrix: Array[Array[Int]], currentRow: Int, currentColumn: Int): Int = {
  val rowCount = matrix.length
  val columnCount = matrix(0).length
  val neighbourDirections = Array((-1, 0), (1, 0), (0, -1), (0, 1))
  var neighbourOneCount = 0

  for ((rowChange, columnChange) <- neighbourDirections) {
    val neighbourRow = currentRow + rowChange
    val neighbourColumn = currentColumn + columnChange

    val isInsideMatrix =
      neighbourRow >= 0 && neighbourRow < rowCount &&
      neighbourColumn >= 0 && neighbourColumn < columnCount

    if (isInsideMatrix && matrix(neighbourRow)(neighbourColumn) == 1) {
      neighbourOneCount += 1
    }
  }

  neighbourOneCount
}

import scala.collection.mutable.ArrayBuffer

def mergeIntervals(intervals: Array[(Int, Int)]): Array[(Int, Int)] = {
  if (intervals.isEmpty) {
    return Array.empty[(Int, Int)]
  }

  val sortedIntervals = intervals.sortBy(interval => interval._1)
  val merged = ArrayBuffer.empty[(Int, Int)]

  var currentStart = sortedIntervals(0)._1
  var currentEnd = sortedIntervals(0)._2

  for (currentIndex <- 1 until sortedIntervals.length) {
    val (nextStart, nextEnd) = sortedIntervals(currentIndex)

    if (nextStart <= currentEnd) {
      currentEnd = math.max(currentEnd, nextEnd)
    } else {
      merged += ((currentStart, currentEnd))
      currentStart = nextStart
      currentEnd = nextEnd
    }
  }

  merged += ((currentStart, currentEnd))
  merged.toArray
}

