def isPalindrome(text: String): Boolean = {
  var leftIndex = 0
  var rightIndex = text.length - 1

  while (leftIndex < rightIndex) {
    if (text(leftIndex) != text(rightIndex)) {
      return false
    }
    leftIndex += 1
    rightIndex -= 1
  }

  true
}

