def partitionByParity(numbers: Array[Int]): Unit = {
  var leftIndex = 0
  var rightIndex = numbers.length - 1

  while (leftIndex < rightIndex) {
    if ((numbers(leftIndex) & 1) == 0) {
      leftIndex += 1
    } else if ((numbers(rightIndex) & 1) != 0) {
      rightIndex -= 1
    } else {
      val temporaryValue = numbers(leftIndex)
      numbers(leftIndex) = numbers(rightIndex)
      numbers(rightIndex) = temporaryValue
      leftIndex += 1
      rightIndex -= 1
    }
  }
}

def countPowersOfTwo(numbers: Array[Int]): Int = {
  var count = 0

  for (number <- numbers) {
    val isPowerOfTwo = number > 0 && (number & (number - 1)) == 0
    if (isPowerOfTwo) {
      count += 1
    }
  }

  count
}

