def buildPrefixSums(numbers: Array[Int]): Array[Long] = {
  val prefixSums = Array.ofDim[Long](numbers.length + 1)

  for (currentIndex <- numbers.indices) {
    prefixSums(currentIndex + 1) = prefixSums(currentIndex) + numbers(currentIndex)
  }

  prefixSums
}

def rangeSum(prefixSums: Array[Long], startIndex: Int, endIndexInclusive: Int): Long = {
  prefixSums(endIndexInclusive + 1) - prefixSums(startIndex)
}
